+  return Buffer.from(JSON.stringify({v:1,i:index}), 'utf8').toString('base64url');
+}
+
+function decodeCursor(cursor) {
+  let parsed;
+  try {
+    parsed = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
+  } catch {
+    throw new Error('Unknown cursor');
+  }
+  if (
+    !parsed || typeof parsed !== 'object' || Array.isArray(parsed) ||
+    parsed.v !== 1 ||
+    typeof parsed.i !== 'number' || !Number.isInteger(parsed.i) ||
+    parsed.i < 0 || parsed.i >= events.length
+  ) {
+    throw new Error('Unknown cursor');
+  }
+  return parsed.i;
+}
