+      properties: {
+        cursor: { type: 'string', description: 'Opaque pagination cursor returned by a previous call.' },
+        page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE, description: 'Number of events per page (1-3, default 2).' }
+      },
+      additionalProperties: false
+    }
+  }];
+}
